                                var skills1 = content.toString().matchAll(/Skill\((?:'|")(.+?)(?:'|")\)/g); //检索技能的content中的Skill
                                var skills2 = content.toString().matchAll(/SkillLog\((?:'|")(.+?)(?:'|")\)/g); //检索技能的content中的SkillLog
