            lib.skill._xushiSkill = {
                enable: 'phaseUse',
                ruleSkill: true,
                charlotte: true,
                forced: true,
                filter(event, player) {
                    var all = player.actionHistory;
                    var skills = [];
                    for (var i = all.length - 1; i >= 0; i--) {
                        for (var x of all[i].useSkill) {
                            skills.add(x.skill);
                        }
                        if (all[i].isRound) break;
                    }
                    for (var i = 0; i < skills.length; i++) {
                        var info = get.info(skills[i]);
                        if (info && info.amass) return false;
                    }
                    return player.countCards('he') > 2 && player.storage.xushiSkill && player.storage.xushiSkill.length;
                },
                filterCard: true,
                position: 'he',
                selectCard: 3,
                check(card) {
                    if (ui.selected.cards.length > 1) return 0;
                    return 4 - get.value(card);
                },
                content() {
                    player.storage.xushiSkill = [];
                    game.log(player, '重置了', '#g蓄势技');
                },
                ai: {
                    order: 3,
                    result: {
                        player: 1,
                    },
                },
                subSkill: {
                    onwash: {
                        trigger: {
                            player: 'pileWashed',
                        },
                        filter(event, player) {
                            return player.storage.xushiSkill && player.storage.xushiSkill.length;
                        },
                        forced: true,
                        ruleSkill: true,
                        charlotte: true,
                        content() {
                            player.storage.xushiSkill = [];
                            game.log(player, '重置了', '#g蓄势技');
                        },
                    },
                },
            };
