            lib.init.css('extension/天牢令', 'Fuhan');
            lib.game.FileExist = function (url) {
                if (window.XMLHttpRequest) {
                    var http = new XMLHttpRequest();
                } else {
                    var http = new ActiveXObject('Microsoft.XMLHTTP');
                }
                http.open('HEAD', url, false);
                try {
                    http.send();
                } catch (err) {
                    return false;
                }
                return http.status != 404;
            };
            lib.game.TLCreateStand = function (player, dialog, height, y) {
                var Tlao_fuhan = ui.create.div('.Tlao_fuhan', dialog);
                Tlao_fuhan.style.setProperty('--h', height + 'px');
                Tlao_fuhan.style.setProperty('--y', y);
                var playerRealSkin = player.style.backgroundImage;
                if (!playerRealSkin) playerRealSkin = player.childNodes[0].style.backgroundImage;
                let playerSkin = playerRealSkin.split('/');
                var reg = new RegExp('[\\u4E00-\\u9FFF]+', 'g');
                var skinStr = playerSkin[playerSkin.length - 1].split('.')[0],
                    skinPath;
                if (reg.test(playerSkin[playerSkin.length - 1])) {
                    skinPath = 'extension/天牢令/image/stand/' + playerSkin[playerSkin.length - 2] + '/' + skinStr + '.jpg';
                } else {
                    skinPath = 'extension/天牢令/image/stand/' + skinStr + '/' + skinStr + '.jpg';
                }
                if (game.FileExist(skinPath)) Tlao_fuhan.style.backgroundImage = 'url(' + skinPath + ')';
                else Tlao_fuhan.style.backgroundImage = playerRealSkin;
            };
            lib.game.TLCreateHead = function (player, dialog, width, x, y) {
                if (typeof player != 'string') player = player.name || '';
                var head = ui.create.div('.Tlao_headpic', dialog);
                head.style.setProperty('--w', width + 'px');
                head.style.left = x + 'px';
                head.style.top = y + 'px';
                var headPath = 'extension/天牢令/image/head/' + player + '/' + player + '.png';
                if (['guanzhang', 'JX_mifangfushiren', 'JX_fanjiangzhangda', 'old_guanzhang', 'sp_mifangfushiren', 'wangfuzhaolei', 'wolongfengchu', 'zhangtongzhaoguang', 'JX_miganfuren', 'JX_zhangzhaozhanghong'].includes(player)) {
                    head.style.backgroundImage = 'url(' + headPath + ')';
                } else {
                    head.setBackground(player, 'character');
                    head.style.backgroundSize = '200%';
                    head.style.backgroundPosition = '50% 10%';
                }
                let headbord = ui.create.div('', head);
                headbord.style.cssText = 'width:100%;height:100%;top:0;left:0;background-size:100%;';
                headbord.style['background-image'] = 'url("extension/天牢令/image/ui/' + game.getRarity(player) + '.png")';
                let headName = ui.create.div('.Tlao_headname', headbord);
                let playerName = get.rawName2(player).slice(0, 5);
                if (playerName.length < 5) headName.style.letterSpacing = '1px';
                headName.textContent = playerName;
            };
            lib.game.TLcreateSkillInfo = function (skill, dialog) {
                var node = ui.create.div('.Tlao_skilltishi', dialog),
                    node1 = ui.create.div('.Tlao_radiusTL', node),
                    node2 = ui.create.div('.Tlao_radiusTR', node),
                    node3 = ui.create.div('.Tlao_radiusBL', node),
                    ndoe4 = ui.create.div('.Tlao_radiusBR', node),
                    topic = ui.create.div('', node),
                    content = ui.create.div('', node);
                topic.style.cssText = 'width:90%;height:20px;font-size:18px;color: #58bf32;font-family:"yuanli";position:absolute;left:5%;top:5px;';
                topic.innerHTML = get.translation(skill);
                content.style.cssText = 'width:90%;height:auto;font-size:13px;font-family:"yuanli";position:absolute;left:5%;top:30px;';
                content.innerHTML = '    ' + get.translation(skill + '_info');
                node.style.setProperty('--h', content.offsetHeight + 38 + 'px');
            };
            lib.game.TLremoveSkillInfo = function () {
                var node = document.getElementsByClassName('Tlao_skilltishi');
                if (!node) return;
                for (var i = 0; i < node.length; i++) {
                    node[i].remove();
                }
            };
            lib.element.player.chooseToFuHan = function (topic, list1, list2, total) {
                var next = game.createEvent('chooseToFuHan');
                next.list1 = list1;
                next.list2 = list2;
                next.topic = topic;
                next.total = total;
                next.player = this;
                next.setContent('chooseToFuHan');
                return next;
            };
            lib.element.content.chooseToFuHan = function () {
                'step 0';
                var list1 = event.list1,
                    list2 = event.list2;
                var switchToAuto = function () {
                    _status.imchoosing = false;
                    var newList = list2.flat();
                    for (var i = 0; i < newList.length; i++) {
                        if (lib.skill[newList[i]].ai && lib.skill[newList[i]].ai.combo) newList.remove(newList[i]);
                    }
                    event._result = {
                        bool: true,
                        skills: newList.randomGets(event.total),
                    };
                    if (event.initbg) event.initbg.close();
                    if (event.control) event.control.close();
                };
                var chooseButton = function (list1, list2) {
                    var event = _status.event;
                    if (!event._result) event._result = {};
                    event._result.skills = [];
                    event.initbg = ui.create.div('.Tlao_initbg', document.body);
                    event.initbg.addEventListener(
                        lib.config.touchscreen ? 'touchend' : 'click',
                        function () {
                            game.TLremoveSkillInfo();
                        },
                        true
                    );
                    var initDialog = ui.create.div('.Tlao_init', event.initbg);
                    initDialog.addEventListener(
                        lib.config.touchscreen ? 'touchend' : 'click',
                        function () {
                            game.TLremoveSkillInfo();
                        },
                        true
                    );
                    initDialog.style.transform = 'translate(-50%,-90%)';
                    var initTopic = ui.create.div('.Tlao_inittishi', initDialog);
                    initTopic.textContent = event.topic;
                    game.TLCreateStand(player, initDialog, 266, 1);
                    var initBord = ui.create.div('', initDialog);
                    initBord.style.cssText = 'width:586px;height:216px;top:33px;right:60px;positon:"absolute";';
                    var skills = event.list2.flat(),
                        num = 0;
                    for (var i = 0; i < event.list1.length; i++) {
                        var x = i * (104 - list1.length * 4) + (8 - list1.length) * 35 + 35;
                        game.TLCreateHead(event.list1[i], initBord, 68, x, 12);
                        for (var j = 0; j < event.list2[i].length; j++) {
                            var td = ui.create.div('.Tlao_skillnode', initBord);
                            if (get.info(list2[i][j]).limited || get.info(list2[i][j]).juexingji) td.classList.add('Tlao_skillnodelimit');
                            td.link = skills[num];
                            num++;
                            td.textContent = get.translation(event.list2[i][j]);
                            td.style.left = x - 3 + 'px';
                            td.style.top = 84 + j * 40 + 'px';
                            td.addEventListener(
                                lib.config.touchscreen ? 'touchend' : 'click',
                                function () {
                                    this.style.animation = 'initbutton 0.2s forwards';
                                    this.addEventListener('animationend', function () {
                                        this.style.animation = '';
                                    });
                                    game.TLremoveSkillInfo();
                                    if (this.classList.contains('Tlao_initselected')) {
                                        this.classList.remove('Tlao_initselected');
                                        event._result.skills.remove(this.link);
                                    } else if (this.classList.contains('Tlao_initselected2')) {
                                        this.classList.remove('Tlao_initselected2');
                                        event._result.skills.remove(this.link);
                                    } else {
                                        if (event._result.skills.length < event.total) {
                                            if (this.classList.contains('Tlao_skillnodelimit')) this.classList.add('initselected2');
                                            else this.classList.add('Tlao_initselected');
                                            event._result.skills.push(this.link);
                                        }
                                        game.TLcreateSkillInfo(this.link, event.initbg);
                                    }
                                },
                                true
                            );
                        }
                    }
                    var prompt = ui.create.div('', initDialog);
                    prompt.style.cssText = 'width:100%;height:20px;left:0;bottom:0;text-align:center;font-family:"yuanli";font-size:20px;line-height:18px;color: #f1dfcc;filter: drop-shadow(1px 0 0 #664934) drop-shadow(-1px 0 0 #664934) drop-shadow(0 1px 0 #664934) drop-shadow(0 -1px 0 #664934);transform:translateY(220%);letter-spacing:3px;pointer-events:none;';
                    prompt.textContent = '请选择' + get.cnNumber(event.total) + '个武将技能';
                    event.switchToAuto = function () {
                        event.initbg.remove();
                        event.control.close();
                        game.resume();
                        _status.imchoosing = false;
                    };
                    event.control = ui.create.control('ok', function (link) {
                        event.initbg.remove();
                        event.control.close();
                        game.resume();
                        _status.imchoosing = false;
                    });
                    game.pause();
                    game.countChoose();
                };
                if (event.isMine()) {
                    chooseButton(list1, list2);
                } else if (event.isOnline()) {
                    event.player.send(chooseButton, list1, list2);
                    event.player.wait();
                    game.pause();
                } else {
                    switchToAuto();
                }
                ('step 1');
                var map = event.result || result;
                if (map && map.skills && map.skills.length) {
                    for (var i of map.skills) {
                        player.removeSkill('DIY_fuhan_effect');
                        lib.skill.DIY_fuhan_effect = lib.skill[i];
                        lib.skill.DIY_fuhan_effect.audioname2 = {};
                        lib.skill.DIY_fuhan_effect.audioname2.JX_zhaoxiang = 'DIY_fuhan';
                        lib.translate.DIY_fuhan_effect_backup = get.translation(i);
                        player.storage.DIY_fuhan_skill = i;
                        var info = get.translation(i + '_info');
                        var txt = '';
                        if (info[info.length - 1] == '.') {
                            for (var i = 0; i < info.length - 1; i++) {
                                txt += info[i];
                            }
                        } else {
                            txt = info;
                        }
                        if (!player.storage.DIY_fuhan) {
                            lib.translate.DIY_fuhan_effect_info = '转换技,锁定技,<span class="bluetext">阴:' + txt + '</span>;阳:同<随机X张蜀势力武将牌中选择的一个技能>(限定技、觉醒技、隐匿技、使命技、主公技除外).';
                        } else {
                            lib.translate.DIY_fuhan_effect_info = '转换技,锁定技,阴:同<随机X张蜀势力武将牌中选择的一个技能>(限定技、觉醒技、隐匿技、使命技、主公技除外);<span class="bluetext">阳:' + txt + '</span>.';
                        }
                        lib.translate.DIY_fuhan_info = '';
                        player.addSkill('DIY_fuhan_effect');
                    }
                }
                event.result = map;
            };
