                                for (var i = 0; i < hs.length; i++) {
                                    var num = 36 - hs[i].number;
                                    for (var j = 0; j < ss.length; j++) {
                                        if (ss[j] == num) {
                                            var k = -1;
                                            bool = true;
                                            break;
                                        }
                                        for (var k = j + 1; k < ss.length; k++) {
                                            if (ss[j].number + ss[k].number == num) {
                                                var l = -1;
                                                bool = true;
                                                break;
                                            }
                                            for (var l = k + 1; l < ss.length; l++) {
                                                if (ss[j].number + ss[k].number + ss[l].number == num) {
                                                    var m = -1;
                                                    bool = true;
                                                    break;
                                                }
                                                for (var m = l + 1; m < ss.length; m++) {
                                                    if (ss[j].number + ss[k].number + ss[l].number + ss[m].number == num) {
                                                        var n = -1;
                                                        bool = true;
                                                        break;
                                                    }
                                                    for (var n = m + 1; n < ss.length; n++) {
                                                        if (ss[j].number + ss[k].number + ss[l].number + ss[m].number + ss[n].number == num) {
                                                            var o = -1;
                                                            bool = true;
                                                            break;
                                                        }
                                                        for (var o = n + 1; o < ss.length; o++) {
                                                            if (ss[j].number + ss[k].number + ss[l].number + ss[m].number + ss[n].number + ss[o].number == num) {
                                                                var p = -1;
                                                                bool = true;
                                                                break;
                                                            }
                                                            for (var p = o + 1; p < ss.length; p++) {
                                                                if (ss[j].number + ss[k].number + ss[l].number + ss[m].number + ss[n].number + ss[o].number + ss[p].number == num) {
                                                                    bool = true;
                                                                    break;
                                                                }
                                                            }
                                                            if (bool) break;
                                                        }
                                                        if (bool) break;
                                                    }
                                                    if (bool) break;
                                                }
                                                if (bool) break;
                                            }
                                            if (bool) break;
                                        }
                                        if (bool) break;
                                    }
                                    if (bool) break;
                                }
                                if (!bool) return [];
                                var list = [i, j, k, l, m, n, o, p];
                                for (var q = 0; q < list.length; q++) {
                                    if (list[q] == -1) {
                                        list = list.slice(0, q);
                                        break;
                                    } else if (q == 0) {
                                        list[q] = hs[i];
                                    } else list[q] = ss[list[q]];
                                }
                                return list;
