                        DIY_qingmo: {
                            audio: 'ext:天牢令/audio:2',
                            trigger: {
                                player: ['useCardAfter', 'respondAfter'],
                            },
                            forced: true,
                            filter(event, player) {
                                var history = player.getHistory('useCard').concat(player.getHistory('respond'));
                                return history.length == 1 && history[0] == event;
                            },
                            content() {
                                'step 0';
                                event.targets1 = game
                                    .filterPlayer(function (current) {
                                        if (current == player) return true;
                                        return current.countCards('h') == player.countCards('h');
                                    })
                                    .sortBySeat();
                                event.targets2 = game
                                    .filterPlayer(function (current) {
                                        if (current == player) return true;
                                        return current.countCards('h') < player.countCards('h');
                                    })
                                    .sortBySeat();
                                if (event.targets1.length > 1) str1 = '与' + get.translation(event.targets1.slice(1)) + '各重铸一张牌';
                                else str1 = '重铸一张牌';
                                if (event.targets2.length > 1) str2 = '与' + get.translation(event.targets2.slice(1)) + '各摸一张牌';
                                else str2 = '摸一张牌';
                                player
                                    .chooseControl('选项一', '选项二', 'cancel2')
                                    .set('choiceList', [str1, str2])
                                    .set('ai', function () {
                                        var player = _status.event.player;
                                        var list1 = _status.event.targets1.slice(0);
                                        var list2 = _status.event.targets2.slice(0);
                                        var num1 = 0,
                                            num2 = 0;
                                        while (list1.length) {
                                            var target = list1.shift();
                                            var att = get.attitude(player, target);
                                            if (att > 0) {
                                                if (target.countCards('he') > 0) num1++;
                                            }
                                            if (att < 0) {
                                                if (target.countCards('he') > 0) num1--;
                                            }
                                        }
                                        while (list2.length) {
                                            var target = list2.shift();
                                            var att = get.attitude(player, target);
                                            if (att > 0) {
                                                num2++;
                                            }
                                            if (att < 0) {
                                                num2--;
                                            }
                                        }
                                        if (num1 > num2) return 0;
                                        else return 1;
                                    })
                                    .set('prompt', get.prompt('DIY_qingmo'))
                                    .set('targets1', event.targets1)
                                    .set('targets2', event.targets2);
                                ('step 1');
                                if (result.control != 'cancel2') {
                                    event.index = result.index;
                                    if (result.index == 1) {
                                        game.asyncDraw(event.targets2);
                                    } else {
                                        event.goto(3);
                                    }
                                } else {
                                    event.finish();
                                }
                                ('step 2');
                                event.finish();
                                ('step 3');
                                event.target = event.targets1.shift();
                                if (event.target.countCards('he') > 0) {
                                    event.target.chooseCard('he', true, '请重铸一张牌');
                                }
                                ('step 4');
                                if (result.bool) {
                                    event.target.loseToDiscardpile(result.cards);
                                    event.target.draw();
                                }
                                if (event.targets1.length) event.goto(3);
                            },
                        },
