                                player.checkConflict('DIY_zhigu');
                                lib.skill.DIY_zhigu.onremove(player, 'DIY_zhigu');
                                player.removeSkillTrigger('DIY_zhigu');
                                player.enableSkill('DIY_zhigu_awake');
