                                delete event.target2;
                                delete event.target3;
                                event.target1 = targets[event.num];
                                for (var i = 1; i < targets.length; i++) {
                                    if (event.num < targets.length - 1) {
                                        if (!event.target2 && targets[event.num + i] && targets[event.num + i].isAlive()) event.target2 = targets[event.num + i];
                                    } else {
                                        if (!event.target2 && targets[-1 + i] && targets[-1 + i].isAlive()) event.target2 = targets[-1 + i];
                                    }
                                    if (!event.target3 && targets[event.num - i] && targets[event.num - i].isAlive()) event.target3 = targets[event.num - i];
                                }
                                if (event.target1 && !event.list.includes(event.target1) && event.target1.isAlive()) {
                                    event.list.add(event.target1);
                                    if (event.target2) {
                                        event.target1
                                            .chooseBool('离魂:视为对' + get.translation(event.target2) + '使用一张【决斗】或失去一点体力')
                                            .set('ai', function () {
                                                return _status.event.effect1 - _status.event.effect2 > 0;
                                            })
                                            .set('effect2', get.effect(target, { name: 'losehp' }, target, target))
                                            .set('effect1', get.effect(event.target1, { name: 'juedou' }, event.target1, event.target2));
                                    } else event.goto(3);
                                } else event.goto(3);
                                ('step 2');
                                if (!result.bool) {
                                    event.target1.loseHp();
                                    if (event.num > 0) {
                                        event.num--;
                                        event.target1.line(event.target3);
                                        event.list.remove(event.target3);
                                        event.goto(1);
                                    }
                                } else event.target1.useCard({ name: 'juedou' }, 'nowuxie', event.target2, 'noai').animate = false;
                                ('step 3');
                                event.num++;
                                if (event.num < 0) event.num = 0;
                                if (event.num < targets.length) event.goto(1);
