                                if (!_status.DIY_zhuyan || !_status.DIY_zhuyan[target.playerid]) return 0;
                                if (player.getStorage('DIY_zhuyan_' + bool).includes(target)) return false;
                                var num = _status.DIY_zhuyan[target.playerid][bool ? 1 : 0];
                                if (bool) {
                                    num -= target.countCards('h');
                                    if (num + target.countCards('h') > 5) num = 5 - target.countCards('h');
                                } else {
                                    num -= target.hp;
                                    if (num + target.hp < 1) num = 1 - target.hp;
                                }
                                return num;
