                                trigger.player.skip('phaseDraw');
                                var list = [];
                                for (var bool of [true, false]) {
                                    var targeted = player.getStorage('DIY_zhuyan_' + bool);
                                    if (!targeted.includes(trigger.player)) list[bool ? 1 : 0] = lib.skill.DIY_zhuyan.getNum(trigger.player, bool, player);
                                    else list[bool ? 1 : 0] = 0;
                                }
                                event.list = list;
