                                if (list[0] && list[1]) {
                                    player
                                        .chooseControl(choices)
                                        .set('choiceList', ['令' + get.translation(trigger.player) + (list[0] > 0 ? '回复' : '失去') + Math.abs(list[0]) + '点体力' + (list[0] < 0 ? '(至多失去至1)' : ''), '令' + get.translation(trigger.player) + (list[1] > 0 ? '摸' : '弃置') + get.cnNumber(Math.abs(list[1])) + '张' + (list[1] > 0 ? '' : '手') + '牌' + (list[1] > 0 ? '(至多摸至5)' : '')])
                                        .set('prompt', '驻颜:请选择一项')
                                        .set('ai', () => _status.event.choice)
                                        .set(
                                            'choice',
                                            (function () {
                                                var v1 = list[0],
                                                    v2 = get.sgn(list[1]) * Math.sqrt(Math.abs(list[1]));
                                                if (get.attitude(player, trigger.player) > 0) {
                                                    return v1 > v2 ? 0 : 1;
                                                }
                                                return v1 > v2 ? 1 : 0;
                                            })()
                                        );
                                } else {
                                    event._result = { index: list[0] ? 0 : 1 };
                                }
                                ('step 1');
                                var ind = result.index;
                                player.markAuto('DIY_zhuyan_' + Boolean(ind), [trigger.player]);
                                var num = event.list[ind];
                                if (ind == 0) {
                                    if (num > 0) {
                                        trigger.player.recover(num);
                                    } else {
                                        num = Math.min(trigger.player.hp - 1, -num);
                                        trigger.player.loseHp(num);
                                    }
                                } else {
                                    if (num > 0) {
                                        num = Math.min(5 - trigger.player.countCards('h'), num);
                                        if (num > 0) trigger.player.draw(num);
                                    } else {
                                        num = -num;
                                        trigger.player.chooseToDiscard(num, true).set('prompt', '驻颜:请弃置' + get.cnNumber(Math.abs(num)) + '张手牌');
                                    }
                                }
