                                    for (var i = history.length - 1; i >= 0; i--) {
                                        if (['basic', 'trick'].includes(get.type(history[i].card))) return '上一张即时牌:' + get.translation(history[i].card.name);
                                    }
                                    return '上一张即时牌:<暂无>';
